mapper.select:


    del_flag = '0'

        and (
            name ILIKE CONCAT('%', #{searchQuery}, '%')
            or name_cn ILIKE CONCAT('%', #{searchQuery}, '%')
            or park_name_cn ILIKE CONCAT('%', #{searchQuery}, '%')
            or industry ILIKE CONCAT('%', #{searchQuery}, '%')
            or tax_code ILIKE CONCAT('%', #{searchQuery}, '%')
            or legal_representative ILIKE CONCAT('%', #{searchQuery}, '%')
        )


        and park_id = #{parkId}


        and industry = #{industry}


        and enterprise_type in

            #{et}



        and enterprise_type = #{enterpriseType}


        and country_of_origin = #{countryOfOrigin}


        and status = #{status}


order by create_time desc nulls last, name_cn asc
